#!/usr/bin/env python3
"""Grade 6 Social Studies (TEKS 113.18.c) - contemporary world cultures. Original questions, about 3 per assessable standard."""
import sys, os
sys.path.insert(0, os.path.dirname(__file__))
from common import *

B = Bank('113.18.c.', 970, own='g6_ss.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# 1 History
H('1.A', 3, "Many countries in South Asia use English in government and business. Which historical event best explains this?", "British colonial rule", ["the Silk Road", "the Cold War space race", "the invention of the printing press"], "Britain ruled much of South Asia for about 200 years.")
H('1.A', 3, "Why do many people in Brazil speak Portuguese instead of Spanish?", "Portugal colonized Brazil", ["Spain traded with Brazil", "Brazil was part of the Roman Empire", "Portuguese was invented there"], "Colonial history shaped language.")
H('1.A', 4, "Why are many borders in Africa straight lines?", "European powers drew them with little regard for ethnic groups", ["Africans designed them as squares", "Rivers formed them", "Mountains formed them"], "Colonial boundaries often ignored local cultures.")
H('1.B', 4, "A region with a long history of trade along ports is most likely to have...", "diverse cultures and languages", ["no outside influence", "only one religion", "no cities"], "Trade brings cultural contact.")
H('1.B', 3, "Why might knowing a country's past help explain present-day conflicts?", "past events can shape borders, grievances and alliances", ["the past never affects the present", "conflicts have no causes", "only maps matter"], "History explains current tensions.")
H('2.A', 3, "Mahatma Gandhi influenced India by leading...", "nonviolent resistance to British rule", ["a naval invasion", "a trade empire", "a space program"], "Gandhi used peaceful protest.")
H('2.A', 3, "Nelson Mandela is known for...", "ending apartheid and becoming South Africa's president", ["inventing the telephone", "founding the Roman Republic", "leading the Mongol army"], "He worked against racial segregation.")
H('2.B', 3, "Which is a cultural contribution of ancient Greece to modern societies?", "ideas about democracy and philosophy", ["gunpowder", "the printing press", "paper money in Europe"], "Greek ideas shaped modern government.")
H('2.B', 3, "Which group is credited with developing the numeral system used worldwide today, including zero?", "mathematicians in India", ["Vikings", "Aztec farmers", "medieval knights"], "Hindu-Arabic numerals began in India.")

