H('3.D', 2, "Which country is in East Asia?", "Japan", ["Peru", "Kenya", "Poland"], "Japan is in East Asia.")
H('3.D', 2, "Which country is in Africa?", "Nigeria", ["Thailand", "Chile", "Ukraine"], "Nigeria is in West Africa.")
H('3.D', 3, "Which country is in South America?", "Argentina", ["Egypt", "India", "Norway"], "Argentina is in South America.")
H('4.A', 3, "Why might a factory be built near a seaport?", "ships can move raw materials and products cheaply", ["ports are always inland", "ports have no goods", "ships cannot carry cargo"], "Ports make shipping easy.")
